{
    switch (x) {
    case INT8_C(1):  return 1;
    case INT16_C(2): return 2;
    case INT32_C(3): return 3;
    case INT64_C(4): return 4;
    default:         return 0;
    }
}

/* [1] 用于枚举常量（要求整型常量表达式） */
