static FILE *(*tmpfile_proto_check)(void) = tmpfile;

int main(void)
{
    /* [1] 原型：调用时不带参数，返回 FILE *。 */
    FILE *fp = tmpfile();
    assert(tmpfile_proto_check == tmpfile);

    /* [4] 成功时应返回非空指针。若返回 NULL 则无法继续测试。 */
