        assert(fputs("hello fclose\n", fp) >= 0);

        /* [2] 成功调用 fclose：flush 缓冲并关闭文件 */
        /* [3] 成功关闭返回 0 */
        int rc = fclose(fp);
        assert(rc == 0);

        /* [2] 验证未写出的缓冲数据确实被交付给宿主环境写入文件 */
        fp = fopen(path, "r");
        assert(fp != NULL);
        char buf[64];
        memset(buf, 0, sizeof buf);
        assert(fgets(buf, sizeof buf, fp) != NULL);
        assert(strcmp(buf, "hello fclose\n") == 0);
